// HARDENED: Transactional Outbox Pattern with Debezium CDC
@Transactional
public void createOrder(Order order) {
    orderRepo.save(order);
    // Atomically persist event into outbox table within same ACID transaction
    outboxRepo.save(new OutboxEvent("orders", order.getId(), order.toJson()));
}
// Debezium captures transaction log (WAL) and guarantees at-least-once Kafka publication
